text:
#imip-view-toolbar > .toolbarbutton-1.message-header-view-button {
  -moz-context-properties: fill, stroke;
  fill: color-mix(in srgb, currentColor 20%, transparent);
  stroke: currentColor;
  margin-inline-start: 6px;
  background-image: var(--imip-button-background);
  border-color: var(--toolbarbutton-header-bordercolor);

  &:not(.imipMoreButton, :active):hover {
    background-image: var(--imip-button-background-hover);
  }

  &:not([is="toolbarbutton-menu-button"], .imipMoreButton):hover:active {
    background-image: var(--imip-button-background-active);
  }

  & > .toolbarbutton-menubutton-button,
  & > .toolbarbutton-menubutton-dropmarker {
    border-color: var(--toolbarbutton-header-bordercolor);
  }

  &.imipMoreButton {
    padding-inline-end: 22px;
    background-image: var(--icon-nav-down-sm), var(--imip-button-background);
    background-position:
      calc(100% - 6px) center,
      0%;
    background-repeat: no-repeat, repeat;

    &:hover {
      background-image: var(--icon-nav-down-sm), var(--imip-button-background-hover);
      background-position:
        calc(100% - 6px) center,
        0%,
        0%;
      background-repeat: no-repeat, repeat, repeat;
    }

    &[open="true"] {
      background-image: var(--icon-nav-down-sm), var(--imip-button-background-active);
      background-position:
        calc(100% - 6px) center,
        0%,
        0%;
      background-repeat: no-repeat, repeat, repeat;
    }

    &:-moz-locale-dir(rtl) {
      background-position-x: 6px, 0%;

      &:hover {
        background-position-x: 6px, 0%, 0%;
      }

      &[open="true"] {
        background-position-x: 6px, 0%, 0%;
      }
    }

    & > .toolbarbutton-icon {
      display: none;
    }
  }
